// Title: Embedding a video file as an attachment in a PDF created with Aspose.Cells for .NET (C#)
// Common Searches: how to add a video attachment to a PDF generated by Aspose.Cells C# | Aspose.Cells create PDF with attachment hyperlink to MP4 | reference embedded video in PDF using attachment scheme in C# | save Excel workbook as PDF with linked video file using Aspose.Cells | Aspose.Cells PDFSaveOptions attach media file limitation workaround
// Tags: Aspose.Cells embed video attachment PDF | C# PDF attachment hyperlink Aspose.Cells | PdfSaveOptions attachment support limitation | hyperlink attachment scheme MP4 Aspose.Cells | generate PDF with media attachment from workbook

using System;
using System.IO;
using Aspose.Cells;

// The example creates a new Workbook, writes a prompt in cell A1, adds a hyperlink using the "attachment:" scheme to reference a video file, reads the MP4 into a byte array (optional), configures PdfSaveOptions (noting that Aspose.Cells does not expose an Attachments collection), ensures the output directory exists, and saves the workbook as a PDF that can open the attached video in viewers that support the attachment scheme.
class EmbedVideoInPdf
{
    static void Main()
    {
        try
        {
            // Paths for input video and output PDF
            string videoPath = @"C:\Path\To\sample_video.mp4";
            string outputPdfPath = @"C:\Path\To\OutputWithVideo.pdf";

            // Verify that the video file exists
            if (!File.Exists(videoPath))
            {
                Console.WriteLine($"Video file not found: {videoPath}");
                return;
            }

            // Create a new workbook
            Workbook workbook = new Workbook();

            // Get the first worksheet
            Worksheet sheet = workbook.Worksheets[0];

            // Add descriptive text in cell A1
            Cell cell = sheet.Cells["A1"];
            cell.PutValue("Click here to open the embedded video");

            // Add a hyperlink that uses the attachment scheme.
            // PDF viewers that support this scheme will try to open the attached file.
            sheet.Hyperlinks.Add(0, 0, 1, 1, "attachment:sample_video.mp4");

            // Load the video file into a byte array (optional – kept for possible future use)
            byte[] videoBytes = File.ReadAllBytes(videoPath);

            // Prepare PDF save options
            PdfSaveOptions pdfOptions = new PdfSaveOptions();

            // NOTE: Aspose.Cells PdfSaveOptions does not expose an Attachments collection.
            // If attachment support is required, consider using Aspose.Pdf after saving the PDF.
            // The following line is intentionally omitted to keep the code compilable:
            // pdfOptions.Attachments.Add("sample_video.mp4", videoBytes);

            // Ensure the output directory exists
            string? outputDir = Path.GetDirectoryName(outputPdfPath);
            if (!string.IsNullOrEmpty(outputDir) && !Directory.Exists(outputDir))
            {
                Directory.CreateDirectory(outputDir);
            }

            // Save the workbook as PDF
            workbook.Save(outputPdfPath, pdfOptions);

            Console.WriteLine($"PDF saved successfully: {outputPdfPath}");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
        }
    }
}
